CREATE TABLE "submission_attempts" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"application_id" uuid NOT NULL,
	"user_id" text NOT NULL,
	"attempt_no" integer NOT NULL,
	"channel" "submit_channel" NOT NULL,
	"ats" "ats_provider" NOT NULL,
	"approved_by" text,
	"phase" text DEFAULT 'claimed' NOT NULL,
	"state" text DEFAULT 'open' NOT NULL,
	"failure_code" text,
	"evidence" jsonb,
	"session_id" text,
	"lease_conflict" boolean DEFAULT false NOT NULL,
	"duplicate_reports" integer DEFAULT 0 NOT NULL,
	"late_confirmation" boolean DEFAULT false NOT NULL,
	"worker_identity" text,
	"browser_launched_at" timestamp with time zone,
	"submit_seen_at" timestamp with time zone,
	"heartbeat_at" timestamp with time zone,
	"started_at" timestamp with time zone DEFAULT now() NOT NULL,
	"finished_at" timestamp with time zone,
	"settled_at" timestamp with time zone,
	CONSTRAINT "submission_attempts_no_ck" CHECK (attempt_no >= 1 AND duplicate_reports >= 0),
	CONSTRAINT "submission_attempts_phase_ck" CHECK (phase IN ('claimed','navigating','filling','submit_seen','reported')),
	CONSTRAINT "submission_attempts_state_ck" CHECK (state IN ('open','submitted','failed','needs_check')),
	CONSTRAINT "submission_attempts_code_ck" CHECK (failure_code IS NULL OR failure_code IN ('challenge','posting_closed','required_missing','applier_error','unconfirmed','timeout',
        'no_report','plan_lapsed','cloud_unavailable_for_ats','extension_reported','render_failed')),
	CONSTRAINT "submission_attempts_approved_by_ck" CHECK (approved_by IS NULL OR approved_by IN ('user','autopilot')),
	CONSTRAINT "submission_attempts_finished_ck" CHECK ((state = 'open') = (finished_at IS NULL)),
	CONSTRAINT "submission_attempts_result_ck" CHECK ((state = 'open' AND failure_code IS NULL)
        OR (state = 'submitted' AND (failure_code IS NULL OR late_confirmation))
        OR (state = 'failed' AND failure_code IS NOT NULL)
        OR (state = 'needs_check' AND failure_code IN ('unconfirmed','timeout','no_report'))),
	CONSTRAINT "submission_attempts_settled_ck" CHECK ((settled_at IS NULL OR state <> 'open')
        AND NOT (state = 'failed' AND settled_at IS NOT NULL AND failure_code IN ('unconfirmed','timeout','no_report'))),
	CONSTRAINT "submission_attempts_channel_ck" CHECK ((channel = 'extension' OR session_id IS NULL)
        AND (channel = 'cloud' OR (worker_identity IS NULL AND browser_launched_at IS NULL AND submit_seen_at IS NULL AND heartbeat_at IS NULL))),
	CONSTRAINT "submission_attempts_evidence_ck" CHECK (evidence IS NULL OR (jsonb_typeof(evidence) = 'object' AND pg_column_size(evidence) <= 4096
        AND NOT (evidence ?| ARRAY['filledFields','values','answers','receipt']))),
	CONSTRAINT "submission_attempts_text_ck" CHECK ((session_id IS NULL OR char_length(session_id) <= 100) AND (worker_identity IS NULL OR char_length(worker_identity) <= 100))
);--> statement-breakpoint
CREATE TABLE "application_events" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "application_events_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"tracker_item_id" uuid NOT NULL,
	"application_id" uuid,
	"user_id" text NOT NULL,
	"kind" text NOT NULL,
	"actor" text NOT NULL,
	"source" text GENERATED ALWAYS AS (CASE WHEN actor = 'user' THEN 'user' ELSE 'system' END) STORED,
	"payload" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"dedupe_key" text,
	"at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "application_events_kind_ck" CHECK (kind IN ('drafted','verified','edited','approved','auto_approved','sent','failed','resent','withdrawn','reply_confirmation',
        'reply_rejection','reply_interview','reply_assessment','reply_offer','gone_quiet','reminder_sent',
        'saved','resume_linked','stage_changed','interview_added','note_added')),
	CONSTRAINT "application_events_actor_ck" CHECK (actor IN ('user','autopilot','system','employer')),
	CONSTRAINT "application_events_app_ck" CHECK (application_id IS NOT NULL OR kind IN ('saved','stage_changed','interview_added','note_added')),
	CONSTRAINT "application_events_dedupe_ck" CHECK (dedupe_key IS NULL OR dedupe_key ~ '^[a-z0-9_:.-]{1,100}$'),
	CONSTRAINT "application_events_payload_ck" CHECK (jsonb_typeof(payload) = 'object' AND pg_column_size(payload) <= 1024
        AND NOT jsonb_path_exists(payload, '$.* ? (@.type() == "object" || @.type() == "array")')
        AND NOT jsonb_path_exists(payload, '$.* ? (@ like_regex "^.{201}")'))
);--> statement-breakpoint
CREATE TABLE "tracker_items" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" text NOT NULL,
	"job_id" uuid,
	"application_id" uuid,
	"title" text,
	"company" text,
	"location" text,
	"url" text,
	"stage" text DEFAULT 'saved' NOT NULL,
	"stage_set_by" text DEFAULT 'system' NOT NULL,
	"closed_reason" text,
	"position" text DEFAULT 'a0' NOT NULL,
	"notes" text,
	"salary_text" text,
	"job_snapshot" jsonb,
	"archived_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "tracker_items_stage_ck" CHECK (stage IN ('saved','drafting','applied','interviewing','offer','closed')),
	CONSTRAINT "tracker_items_stage_set_by_ck" CHECK (stage_set_by IN ('system','user')),
	CONSTRAINT "tracker_items_closed_ck" CHECK ((stage = 'closed') = (closed_reason IS NOT NULL)
        AND (closed_reason IS NULL OR closed_reason IN ('rejected','withdrawn','not_pursuing','posting_closed'))),
	CONSTRAINT "tracker_items_text_ck" CHECK ((title IS NULL OR char_length(title) BETWEEN 1 AND 500) AND (company IS NULL OR char_length(company) BETWEEN 1 AND 200)
        AND (location IS NULL OR char_length(location) <= 500) AND (url IS NULL OR (char_length(url) <= 2000 AND url ~* '^https?://'))
        AND (notes IS NULL OR char_length(notes) <= 20000) AND (salary_text IS NULL OR char_length(salary_text) <= 200)
        AND char_length(position) BETWEEN 1 AND 64),
	CONSTRAINT "tracker_items_snapshot_ck" CHECK (job_snapshot IS NULL OR (jsonb_typeof(job_snapshot) = 'object' AND octet_length(job_snapshot::text) <= 65536))
);--> statement-breakpoint
