-- companies_fill_hosts: the poll and apply hosts follow from (ats, api_region) unless a writer sets them (B-5 rule:
-- Greenhouse applies on job-boards.greenhouse.io, the host services/ats builds). companies_hosts_ck then allows only
-- the allowlisted pairs. Fires on UPDATE OF the host columns too, so 0011's backfill is one no-op update.
CREATE FUNCTION companies_fill_hosts() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.api_host := coalesce(NEW.api_host, CASE NEW.ats::text
    WHEN 'greenhouse' THEN 'boards-api.greenhouse.io'
    WHEN 'lever' THEN CASE NEW.api_region WHEN 'eu' THEN 'api.eu.lever.co' ELSE 'api.lever.co' END
    WHEN 'ashby' THEN 'api.ashbyhq.com' END);
  NEW.apply_host := coalesce(NEW.apply_host, CASE NEW.ats::text
    WHEN 'greenhouse' THEN 'job-boards.greenhouse.io'
    WHEN 'lever' THEN CASE NEW.api_region WHEN 'eu' THEN 'jobs.eu.lever.co' ELSE 'jobs.lever.co' END
    WHEN 'ashby' THEN 'jobs.ashbyhq.com' END);
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER companies_fill_hosts_biu BEFORE INSERT OR UPDATE OF api_host, apply_host ON companies
  FOR EACH ROW EXECUTE FUNCTION companies_fill_hosts();--> statement-breakpoint

-- matches_status_guard (02-database 8.3, R-18): a user decision (queued, skipped) is never overridden; the system moves
-- only among new, below_bar and expired. 'ops' and 'migration:<name>' are operator repairs and backfills.
CREATE FUNCTION matches_status_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_actor text := kairos_actor();
BEGIN
  IF NEW.status = OLD.status THEN RETURN NEW; END IF;
  IF v_actor = 'ops' OR v_actor LIKE 'migration:%' THEN
    NULL;
  ELSIF v_actor = 'user' THEN
    IF NEW.status::text NOT IN ('queued','skipped') THEN
      RAISE EXCEPTION 'a user action can only queue or skip a match' USING ERRCODE = '23514', CONSTRAINT = 'matches_status_guard';
    END IF;
  ELSIF v_actor = 'autopilot' THEN
    IF NOT (OLD.status::text = 'new' AND NEW.status::text = 'queued') THEN
      RAISE EXCEPTION 'Autopilot can only queue a new match' USING ERRCODE = '23514', CONSTRAINT = 'matches_status_guard';
    END IF;
  ELSE
    IF OLD.status::text IN ('queued','skipped') THEN
      RAISE EXCEPTION 'the system never overrides a user decision (% -> %)', OLD.status, NEW.status
        USING ERRCODE = '23514', CONSTRAINT = 'matches_status_guard';
    END IF;
    IF (OLD.status::text, NEW.status::text) NOT IN (('new','below_bar'), ('new','expired'), ('below_bar','new'),
                                                    ('below_bar','expired'), ('expired','new')) THEN
      RAISE EXCEPTION 'illegal system match transition % -> %', OLD.status, NEW.status
        USING ERRCODE = '23514', CONSTRAINT = 'matches_status_guard';
    END IF;
  END IF;
  NEW.status_changed_at := now();
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER matches_status_guard_bu BEFORE UPDATE OF status ON matches
  FOR EACH ROW EXECUTE FUNCTION matches_status_guard();--> statement-breakpoint

-- Status guard version 1, final text (_db/applications.md 5.3): 0006's transitions plus the late-confirmation rule and
-- terminal_at. Versions 2 and 3 (the draft_state and verification gates) wait for their soaks.
CREATE OR REPLACE FUNCTION applications_guard_status() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status = OLD.status THEN RETURN NEW; END IF;
  IF (OLD.status::text, NEW.status::text) NOT IN (
       ('draft','approved'),      ('draft','withdrawn'),
       ('approved','submitting'), ('approved','submitted'), ('approved','failed'),
       ('approved','withdrawn'),  ('approved','draft'),
       ('submitting','submitted'),('submitting','failed'),  ('submitting','approved'),
       ('failed','approved'),     ('failed','submitted'),   ('failed','withdrawn')) THEN
    RAISE EXCEPTION 'illegal application transition % -> %', OLD.status, NEW.status
      USING ERRCODE = '23514', CONSTRAINT = 'applications_status_guard';
  END IF;
  IF OLD.status = 'submitting' AND NEW.status = 'approved' AND NEW.channel IS DISTINCT FROM 'extension' THEN
    RAISE EXCEPTION 'only an extension claim can be released' USING ERRCODE = '23514', CONSTRAINT = 'applications_status_guard';
  END IF;
  IF OLD.status = 'failed' AND NEW.status = 'submitted'
     AND (OLD.failure_code IS NULL OR OLD.failure_code NOT IN ('unconfirmed','timeout','no_report')) THEN
    RAISE EXCEPTION 'a failed application can be confirmed late only after unconfirmed, timeout or no_report'
      USING ERRCODE = '23514', CONSTRAINT = 'applications_status_guard';
  END IF;
  NEW.updated_at := now();
  NEW.terminal_at := CASE WHEN NEW.status IN ('submitted','failed','withdrawn') THEN now() ELSE NULL END;
  RETURN NEW;
END $$;--> statement-breakpoint

-- draft_state: expired is terminal; stage: forward only, rejected final, null may become anything (_db/applications.md 5.3).
CREATE FUNCTION applications_guard_draft_state() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.draft_state = 'expired' AND NEW.draft_state <> 'expired' THEN
    RAISE EXCEPTION 'an expired draft cannot change state' USING ERRCODE = '23514', CONSTRAINT = 'applications_draft_state_guard';
  END IF;
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER applications_guard_draft_state_bu BEFORE UPDATE OF draft_state ON applications
  FOR EACH ROW EXECUTE FUNCTION applications_guard_draft_state();--> statement-breakpoint
CREATE FUNCTION applications_guard_stage() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE ranks text[] := ARRAY['applied','in_review','assessment','interviewing','offer'];
BEGIN
  IF NEW.stage IS NOT DISTINCT FROM OLD.stage THEN RETURN NEW; END IF;
  IF OLD.stage = 'rejected' THEN
    RAISE EXCEPTION 'stage rejected is final' USING ERRCODE = '23514', CONSTRAINT = 'applications_stage_guard';
  END IF;
  IF OLD.stage IS NULL OR NEW.stage = 'rejected' THEN RETURN NEW; END IF;
  IF NEW.stage IS NULL OR array_position(ranks, NEW.stage) <= array_position(ranks, OLD.stage) THEN
    RAISE EXCEPTION 'stage cannot move backward (% to %)', OLD.stage, NEW.stage USING ERRCODE = '23514', CONSTRAINT = 'applications_stage_guard';
  END IF;
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER applications_guard_stage_bu BEFORE UPDATE OF stage ON applications
  FOR EACH ROW EXECUTE FUNCTION applications_guard_stage();--> statement-breakpoint

-- applications_row_version (02-database 8.3, 05-api DB-1): the ETag moves by exactly one when a client-visible column
-- changes, whatever the statement set; lease, pointer and timestamp-only updates keep it. Named to run last (8.4).
CREATE FUNCTION applications_row_version() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (NEW.status, NEW.draft_state, NEW.draft_issue, NEW.revision, NEW.verification, NEW.resume_lines, NEW.resume_line_entries,
      NEW.answers, NEW.cover_letter, NEW.resume_snapshot, NEW.resume_file_key, NEW.receipt, NEW.receipt_summary, NEW.failure_code,
      NEW.failure_reason, NEW.stage, NEW.channel, NEW.approved_at, NEW.content_scrubbed_at)
     IS DISTINCT FROM
     (OLD.status, OLD.draft_state, OLD.draft_issue, OLD.revision, OLD.verification, OLD.resume_lines, OLD.resume_line_entries,
      OLD.answers, OLD.cover_letter, OLD.resume_snapshot, OLD.resume_file_key, OLD.receipt, OLD.receipt_summary, OLD.failure_code,
      OLD.failure_reason, OLD.stage, OLD.channel, OLD.approved_at, OLD.content_scrubbed_at) THEN
    NEW.row_version := OLD.row_version + 1;
  ELSE
    NEW.row_version := OLD.row_version;
  END IF;
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER applications_row_version_bu BEFORE UPDATE ON applications
  FOR EACH ROW EXECUTE FUNCTION applications_row_version();--> statement-breakpoint

-- submission_attempts_guard (_db/applications.md 5.4): identity immutable, phase forward only, legal state pairs, a
-- closed attempt final unless its outcome was ambiguous; finished_at, submit_seen_at and late_confirmation are its.
CREATE FUNCTION submission_attempts_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE ranks text[] := ARRAY['claimed','navigating','filling','submit_seen','reported'];
BEGIN
  IF (NEW.application_id, NEW.user_id, NEW.attempt_no, NEW.channel, NEW.ats, NEW.started_at)
       IS DISTINCT FROM (OLD.application_id, OLD.user_id, OLD.attempt_no, OLD.channel, OLD.ats, OLD.started_at) THEN
    RAISE EXCEPTION 'submission_attempts identity columns are immutable' USING ERRCODE = '23514', CONSTRAINT = 'submission_attempts_guard';
  END IF;
  IF array_position(ranks, NEW.phase) < array_position(ranks, OLD.phase) THEN
    RAISE EXCEPTION 'attempt phase cannot move backward (% to %)', OLD.phase, NEW.phase USING ERRCODE = '23514', CONSTRAINT = 'submission_attempts_guard';
  END IF;
  IF NEW.phase = 'submit_seen' AND OLD.phase <> 'submit_seen' AND NEW.submit_seen_at IS NULL THEN
    NEW.submit_seen_at := now();
  END IF;
  IF NEW.state <> OLD.state THEN
    IF (OLD.state, NEW.state) NOT IN (('open','submitted'), ('open','failed'), ('open','needs_check'),
                                      ('failed','needs_check'), ('failed','submitted'), ('needs_check','submitted')) THEN
      RAISE EXCEPTION 'illegal attempt transition % -> %', OLD.state, NEW.state USING ERRCODE = '23514', CONSTRAINT = 'submission_attempts_guard';
    END IF;
    IF OLD.state <> 'open' AND OLD.failure_code NOT IN ('unconfirmed','timeout','no_report') THEN
      RAISE EXCEPTION 'a closed attempt with code % is final', OLD.failure_code USING ERRCODE = '23514', CONSTRAINT = 'submission_attempts_guard';
    END IF;
    IF OLD.state = 'open' AND NEW.finished_at IS NULL THEN NEW.finished_at := now(); END IF;
    IF OLD.state IN ('failed','needs_check') AND NEW.state = 'submitted' THEN NEW.late_confirmation := true; END IF;
  ELSIF OLD.state <> 'open' AND NEW.failure_code IS DISTINCT FROM OLD.failure_code THEN
    RAISE EXCEPTION 'a closed attempt keeps its failure code' USING ERRCODE = '23514', CONSTRAINT = 'submission_attempts_guard';
  END IF;
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER submission_attempts_guard_bu BEFORE UPDATE ON submission_attempts
  FOR EACH ROW EXECUTE FUNCTION submission_attempts_guard();--> statement-breakpoint

-- application_events is append-only for everyone, the owner included (_db/applications.md 5.5); only a cascade deletes.
CREATE FUNCTION application_events_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' AND pg_trigger_depth() >= 2 THEN RETURN OLD; END IF;
  RAISE EXCEPTION 'application_events is append-only (% blocked)', TG_OP USING ERRCODE = '42501';
END $$;--> statement-breakpoint
CREATE TRIGGER application_events_immutable_bud BEFORE UPDATE OR DELETE ON application_events
  FOR EACH ROW EXECUTE FUNCTION application_events_immutable();--> statement-breakpoint

-- Same-owner references (assert_same_owner, 0007): an attempt, a tracker item or an event never points at another
-- user's application or item.
CREATE TRIGGER submission_attempts_owner_application BEFORE INSERT OR UPDATE OF user_id, application_id ON submission_attempts
  FOR EACH ROW EXECUTE FUNCTION assert_same_owner('applications', 'application_id');--> statement-breakpoint
CREATE TRIGGER tracker_items_owner_application BEFORE INSERT OR UPDATE OF user_id, application_id ON tracker_items
  FOR EACH ROW EXECUTE FUNCTION assert_same_owner('applications', 'application_id');--> statement-breakpoint
CREATE TRIGGER application_events_owner_application BEFORE INSERT ON application_events
  FOR EACH ROW EXECUTE FUNCTION assert_same_owner('applications', 'application_id');--> statement-breakpoint
CREATE TRIGGER application_events_owner_item BEFORE INSERT ON application_events
  FOR EACH ROW EXECUTE FUNCTION assert_same_owner('tracker_items', 'tracker_item_id');
